51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
53	const BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	};
58	
59	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
60	// separate term rather than folded into a `base * 1.1` factor, which is not
61	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
62	const quotePremium = (items: Item[]): number => {
63	  const base = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
64	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE);
65	};
66	
67	const quote = (step: QuoteStep): QuoteResult => ({
68	  premium: quotePremium(step.items),
69	});
70	
71	const runStep = (step: Step): Result => {
72	  switch (step.op) {
73	    case "quote":
74	      return quote(step);
75	    default:
76	      throw new Error(`unsupported step: ${step.op}`);
77	  }
78	};
79	
80	export const runScenario = (scenario: Scenario): ScenarioResult => ({
81	  results: scenario.steps.map(runStep),
82	});
